import{_ as a,o as s,c as n,a2 as d}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"01 · 导演执行稿","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/03f-tomato-sensory-film.md","filePath":"lab/shuangyu-fries/03f-tomato-sensory-film.md","lastUpdated":1787456457000}'),e={name:"lab/shuangyu-fries/03f-tomato-sensory-film.md"};function p(l,t,i,r,o,h){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="_01-·-导演执行稿" tabindex="-1">01 · 导演执行稿 <a class="header-anchor" href="#_01-·-导演执行稿" aria-label="Permalink to &quot;01 · 导演执行稿&quot;">​</a></h1><blockquote><p>番茄味独立感官创意片 ｜ 20 秒 / 6 镜头 / 16:9 横屏主版</p></blockquote><h2 id="影片定位" tabindex="-1">影片定位 <a class="header-anchor" href="#影片定位" aria-label="Permalink to &quot;影片定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>产品</td><td>双宇食品「薯条脆」番茄味，46g 杯装</td></tr><tr><td>片型</td><td>单口味感官创意片 / ASMR 食品广告</td></tr><tr><td>主诉求</td><td>番茄风味识别，其次是酥脆口感</td></tr><tr><td>创意概念</td><td><strong>番茄香，咔嚓脆</strong></td></tr><tr><td>视觉主线</td><td>番茄红风味颗粒靠近 → 附着 → 断裂爆开 → 开杯入口 → 产品落版</td></tr><tr><td>色彩结构</td><td>包装橙红、番茄红、浅金薯条色，少量奶油白作高光背景</td></tr><tr><td>声音策略</td><td>调味颗粒落下声、碰撞声、掰断声；无旁白，咔嚓声是主角</td></tr><tr><td>总时长</td><td><strong>20 秒</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">传播边界</p><p>本片卖的是口味和感官，不展开 VF 工艺。除非技术方确认本产品的具体工艺参数，否则不出现「80–90℃」「离心脱油」等字幕。</p><p>如果配料表尚未确认含真实番茄或番茄原料，画面只使用番茄红色、抽象调味颗粒和风味光影，不出现「真番茄」「番茄汁淋在薯条上」等暗示。</p></div><h2 id="_20-秒时间线" tabindex="-1">20 秒时间线 <a class="header-anchor" href="#_20-秒时间线" aria-label="Permalink to &quot;20 秒时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>镜头</th><th>画面与动作</th><th>声音</th><th>字幕</th></tr></thead><tbody><tr><td>00:00–00:03</td><td>01 · 红色风味靠近</td><td>黑场中一根浅金色薯条脆被窄光扫亮；番茄红微粒从远处聚拢</td><td>极轻空气移动声，末尾一声短促「咔」</td><td>无</td></tr><tr><td>00:03–00:06</td><td>02 · 番茄颗粒落附</td><td>红色调味颗粒落在薯条脆表面，微距展示干爽纹理与颗粒附着</td><td>细密颗粒落下声逐渐加快</td><td><strong>番茄味</strong></td></tr><tr><td>00:06–00:10</td><td>03 · 一折即脆</td><td>薯条脆从中央干净断开，断面透光，真实碎屑向外飞散</td><td>0.15 秒静音后，一记近距离主「咔嚓」</td><td><strong>咔嚓酥脆</strong></td></tr><tr><td>00:10–00:13</td><td>04 · 风味成形</td><td>多根薯条脆交错落下，红色微粒形成克制的弧形风味轨迹</td><td>两次轻脆碰撞，接入节拍</td><td>无</td></tr><tr><td>00:13–00:17</td><td>05 · 开杯取食</td><td>撕开铝箔，薯条脆从杯中倒出；手指拿起一根，停在镜头前</td><td>撕膜声、干爽落料声、一次轻咬声</td><td><strong>番茄香，咔嚓脆</strong></td></tr><tr><td>00:17–00:20</td><td>06 · 产品落版</td><td>番茄味包装正面朝镜头，薯条脆在前景形成放射构图，碎屑慢慢落定</td><td>最后一声干净「咔嚓」，音乐收住</td><td><strong>双宇食品 · 薯条脆</strong><br><strong>番茄味</strong></td></tr></tbody></table><h2 id="视觉执行标准" tabindex="-1">视觉执行标准 <a class="header-anchor" href="#视觉执行标准" aria-label="Permalink to &quot;视觉执行标准&quot;">​</a></h2><p>全片保持同一款产品外观：浅金色粗长条、平直切面、表面干爽哑光、细小红色调味颗粒、断面疏松多孔。红色是番茄口味的识别资产，但不要把画面做成番茄酱广告。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高端商业食品广告摄影，真实食物质感，微距与高速摄影结合；</span></span>
<span class="line"><span>浅金色粗条状薯条脆，平直长方体轮廓，边缘有自然缺口，表面干爽哑光，</span></span>
<span class="line"><span>细小番茄红调味颗粒均匀但不规则地附着，断面为真实不规则多孔结构；</span></span>
<span class="line"><span>包装橙红、番茄红、浅金色和奶油白构成主色，明快、食欲感强，不过度饱和；</span></span>
<span class="line"><span>轻微胶片颗粒，自然色彩，真实商业食品摄影。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：深褐色、焦黑、油腻反光、表面浮油、普通细薯条、软塌弯曲、</span></span>
<span class="line"><span>挤压膨化棒、威化棒、饼干棒、面包断面、规则蜂巢、塑料感、卡通、插画、</span></span>
<span class="line"><span>火焰、爆炸烟雾、金属粒子、文字、水印、伪造 logo、伪造包装。</span></span></code></pre></div><h2 id="逐镜执行" tabindex="-1">逐镜执行 <a class="header-anchor" href="#逐镜执行" aria-label="Permalink to &quot;逐镜执行&quot;">​</a></h2><h3 id="_01-·-红色风味靠近" tabindex="-1">01 · 红色风味靠近 <a class="header-anchor" href="#_01-·-红色风味靠近" aria-label="Permalink to &quot;01 · 红色风味靠近&quot;">​</a></h3><p>只表达“番茄风味即将出现”。黑底负责建立高级感，红色微粒负责口味识别。不要出现第二根产品，也不要使用番茄酱液体特效。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纯黑影棚空间中，一根浅金色粗条状薯条脆水平悬浮在中央，保持平直轮廓、</span></span>
<span class="line"><span>浅金色、干爽哑光和自然马铃薯纹理；远处只有一团失焦的番茄红暖光缓慢靠近，</span></span>
<span class="line"><span>少量细小红色食物调味颗粒在光中悬浮，颗粒不接触产品；窄幅暖金轮廓光扫过上缘，</span></span>
<span class="line"><span>画面安静、克制、有食欲。</span></span>
<span class="line"><span>100mm 微距，f/4，浅景深，黑红高反差，16:9 横屏。</span></span>
<span class="line"><span>禁止：番茄酱、液体、烟雾、火焰、第二根产品、包装、文字、水印。</span></span></code></pre></div><p>视频动作：红色光斑在 3 秒内缓慢横移约画面宽度的 20%，产品只做轻微推进，不旋转、不变形。</p><h3 id="_02-·-番茄颗粒落附" tabindex="-1">02 · 番茄颗粒落附 <a class="header-anchor" href="#_02-·-番茄颗粒落附" aria-label="Permalink to &quot;02 · 番茄颗粒落附&quot;">​</a></h3><p>这一镜是口味的直接证据：让观众看见“番茄味”附着在薯条脆上。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一根浅金色粗条状薯条脆斜置于画面中央，极致微距展示干爽粗粝表面；</span></span>
<span class="line"><span>细小番茄红调味颗粒从上方自然落下，轻轻弹跳后附着在表面凹凸处，</span></span>
<span class="line"><span>分布均匀但不规则，没有液体、油滴或黏稠质感；背景为奶油白到浅橙红的柔和渐层。</span></span>
<span class="line"><span>100mm 微距，高速摄影定格感，侧逆光照亮颗粒边缘，16:9 横屏。</span></span>
<span class="line"><span>禁止：番茄汁、酱料淋洒、湿润表面、油膜、金属粉尘、文字、水印。</span></span></code></pre></div><p>视频动作：颗粒由稀到密落下，镜头沿薯条脆表面做一次短距离滑轨，焦点跟随一颗红色颗粒，结尾推进到表面裂纹。</p><h3 id="_03-·-一折即脆" tabindex="-1">03 · 一折即脆 <a class="header-anchor" href="#_03-·-一折即脆" aria-label="Permalink to &quot;03 · 一折即脆&quot;">​</a></h3><p>全片最重要的感官证明。必须使用首尾帧控制，先把完整条和断裂后的断面分别做准，再生成中间动作。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两枚自然结构的指尖捏住一根浅金色粗条状薯条脆两端，薯条脆刚从中央断裂，</span></span>
<span class="line"><span>两段参差断口朝向镜头，清晰可见真实不规则多孔结构；少量金色食物碎屑从断裂点飞出，</span></span>
<span class="line"><span>强逆光穿透部分孔洞并照亮碎屑边缘，背景由番茄红渐变压暗为深黑。</span></span>
<span class="line"><span>100mm 微距，1000fps 超高速摄影，正侧面特写，16:9 横屏。</span></span>
<span class="line"><span>禁止：面包断面、海绵、规则蜂巢、额外手指、断裂愈合、烟花、火焰、塑料感。</span></span></code></pre></div><p>视频动作：前 0.8 秒保持稳定，随后干净断开；断裂瞬间升格 0.25 秒，再恢复速度。产品长度、碎屑数量和手指结构必须逐条检查。</p><h3 id="_04-·-风味成形" tabindex="-1">04 · 风味成形 <a class="header-anchor" href="#_04-·-风味成形" aria-label="Permalink to &quot;04 · 风味成形&quot;">​</a></h3><p>把红色风味颗粒和浅金色产品组成一条流动的视觉节奏，避免把特效做成抽象烟雾。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三根浅金色粗条状薯条脆在明亮奶油白空间中交错落下，表面都有细小番茄红调味颗粒；</span></span>
<span class="line"><span>红色颗粒和少量真实食物碎屑沿弧形轨迹向中央汇聚，形成轻盈、克制的风味流线，</span></span>
<span class="line"><span>产品始终保持干爽哑光和自然比例，背景干净，红、金、白三色清晰分层。</span></span>
<span class="line"><span>50mm 中近景，略微低机位，柔和顶光加红金轮廓光，16:9 横屏。</span></span>
<span class="line"><span>禁止：爆炸、烟雾、金属粒子、液体飞溅、深褐色、包装文字、水印。</span></span></code></pre></div><p>视频动作：分别生成三根薯条脆落下、两根碰撞、碎屑汇聚三个短片段，后期剪成连续节奏，不让模型一次完成全部动作。</p><h3 id="_05-·-开杯取食" tabindex="-1">05 · 开杯取食 <a class="header-anchor" href="#_05-·-开杯取食" aria-label="Permalink to &quot;05 · 开杯取食&quot;">​</a></h3><p>杯装包装的动作价值在这一镜体现：撕膜、倒出、拿起，比单纯摆包装更有记忆点。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用客户确认的番茄味薯条脆包装作为唯一包装参考，保持杯身比例、橙红版式、</span></span>
<span class="line"><span>杯口结构和品牌图形不变；一只手从右上方撕开铝箔封膜，杯中浅金色薯条脆向前倾倒，</span></span>
<span class="line"><span>细小红色调味颗粒清晰可见，另一枚指尖从落料中拿起一根薯条脆；</span></span>
<span class="line"><span>背景为干净暖奶油色，红色包装和浅金产品保持清晰分离。</span></span>
<span class="line"><span>85mm 特写，柔和侧逆光，真实商业食品摄影，16:9 横屏。</span></span>
<span class="line"><span>禁止：包装变形、文字改写、伪造 logo、多人、咬脸、油滴、蒸汽、水印。</span></span></code></pre></div><p>包装文字和 logo 必须用后期合成；生成模型只负责动作和光影。</p><h3 id="_06-·-产品落版" tabindex="-1">06 · 产品落版 <a class="header-anchor" href="#_06-·-产品落版" aria-label="Permalink to &quot;06 · 产品落版&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成不含包装的干净暖奶油色影棚背景，画面中央预留杯装产品的直立位置；</span></span>
<span class="line"><span>三根浅金色薯条脆在预留位置前方形成放射构图，表面有细小番茄红调味颗粒，</span></span>
<span class="line"><span>干爽哑光；少量真实食物碎屑从上方落下并在台面停住，左侧留出字幕安全区。</span></span>
<span class="line"><span>50mm 产品英雄镜头，正面柔光确保包装可读，暖金轮廓光，16:9 横屏。</span></span>
<span class="line"><span>禁止：假包装、改字、伪造 logo、额外产品、深褐色食物、油腻反光、水印。</span></span></code></pre></div><p>后期将客户确认的真实包装图合成到预留位置，最后 1.5 秒锁定产品，不再切镜。</p><h2 id="声音执行" tabindex="-1">声音执行 <a class="header-anchor" href="#声音执行" aria-label="Permalink to &quot;声音执行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>声音层</th><th>处理方式</th></tr></thead><tbody><tr><td>风味靠近</td><td>轻微空气移动声，音量低，不做液体声</td></tr><tr><td>调味颗粒</td><td>录制细盐或调味粉落在纸面上的细密声</td></tr><tr><td>主咔嚓</td><td>实录薯条脆近距离折断，断裂前留 0.15 秒静音</td></tr><tr><td>碎屑</td><td>轻微干燥颗粒掠过声，避免金属或玻璃质感</td></tr><tr><td>开杯</td><td>铝箔撕开声、倒料声、杯内碰撞声分层处理</td></tr><tr><td>音乐</td><td>90–100 BPM，前半段克制，断裂后进入轻快节奏；无旁白</td></tr></tbody></table><h2 id="后期字幕建议" tabindex="-1">后期字幕建议 <a class="header-anchor" href="#后期字幕建议" aria-label="Permalink to &quot;后期字幕建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入点</th><th>文案</th></tr></thead><tbody><tr><td>00:03.2</td><td><strong>番茄味</strong></td></tr><tr><td>00:09.8</td><td><strong>咔嚓酥脆</strong></td></tr><tr><td>00:14.0</td><td><strong>番茄香，咔嚓脆</strong></td></tr><tr><td>00:17.2</td><td><strong>双宇食品 · 薯条脆</strong></td></tr><tr><td>00:18.0</td><td><strong>番茄味</strong></td></tr></tbody></table><p>以上是工作文案，最终需结合配料表、产品品鉴和法务确认。不要增加“浓郁到停不下来”“绝对酥脆”等绝对化或无法证明的表述。</p><h2 id="生成与剪辑拆分" tabindex="-1">生成与剪辑拆分 <a class="header-anchor" href="#生成与剪辑拆分" aria-label="Permalink to &quot;生成与剪辑拆分&quot;">​</a></h2><p>视频模型不要一次生成完整 20 秒，建议拆为 7 段：</p><table tabindex="0"><thead><tr><th>段落</th><th style="text-align:right;">生成长度</th><th>对应镜头</th></tr></thead><tbody><tr><td>A</td><td style="text-align:right;">3 秒</td><td>红色风味靠近</td></tr><tr><td>B</td><td style="text-align:right;">3 秒</td><td>调味颗粒落附</td></tr><tr><td>C1 / C2</td><td style="text-align:right;">各 2 秒</td><td>掰断首帧到尾帧、断裂碎屑</td></tr><tr><td>D1 / D2</td><td style="text-align:right;">各 1.5 秒</td><td>薯条落下、风味流线汇聚</td></tr><tr><td>E</td><td style="text-align:right;">4 秒</td><td>开杯、倒出、取食</td></tr><tr><td>F</td><td style="text-align:right;">3 秒</td><td>产品落版背景与碎屑</td></tr></tbody></table><p>先做产品母版和断面关键帧，再生成动作；包装和字幕最后合成。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>第一秒至第三秒能看见番茄红的风味线索，而不是泛泛的薯片广告。</li><li>红色颗粒必须像真实调味粉，不能像金属粉、烟花或数字粒子。</li><li>薯条脆保持浅金、粗长条、干爽哑光，不变成普通细薯条或膨化棒。</li><li>断面真实可读，断裂过程不能愈合、增生或改变长度。</li><li>包装文字、logo、杯盖和口味名全部来自真实物料。</li><li>全片不出现未经确认的健康、营养、真实番茄原料或 VF 参数承诺。</li><li>声音能让观众分辨“调味落下”和“薯条脆断裂”是两种不同动作。</li></ul><h2 id="开始制作前需确认" tabindex="-1">开始制作前需确认 <a class="header-anchor" href="#开始制作前需确认" aria-label="Permalink to &quot;开始制作前需确认&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>影响</th></tr></thead><tbody><tr><td>番茄味终版配料表或产品品鉴描述</td><td>决定能否出现真实番茄、酸甜等具体意象</td></tr><tr><td>包装终稿源文件 / 实物杯</td><td>决定镜头 5、6 能否完成准确包装合成</td></tr><tr><td>主投放比例</td><td>当前主版为 16:9 横屏；如需社媒竖版，再从中心构图另行适配</td></tr><tr><td>主文案与法务口径</td><td>决定“番茄香”等感官词能否进入成片</td></tr></tbody></table>`,47)])])}const g=a(e,[["render",p]]);export{b as __pageData,g as default};
